package org.msa.graphics;
import android.app.Activity;import android.os.Bundle;import android.webkit.*;import androidx.webkit.WebViewAssetLoader;
public class MainActivity extends Activity {private ValueCallback<android.net.Uri[]> fileCallback;protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(request==71&&fileCallback!=null){ValueCallback<android.net.Uri[]> cb=fileCallback;fileCallback=null;cb.onReceiveValue(result==RESULT_OK&&data!=null&&data.getData()!=null?new android.net.Uri[]{data.getData()}:null);}}private WebView view;private NativeScene nativeScene;private android.widget.FrameLayout host;private boolean nativeMode;private android.os.PowerManager power;private final android.os.PowerManager.OnThermalStatusChangedListener thermal=status->{if(nativeScene!=null)nativeScene.thermal(status);if(view!=null&&!nativeMode)view.evaluateJavascript("if(window.msaThermalStatus)window.msaThermalStatus("+status+")",null);};public void onCreate(Bundle b){super.onCreate(b);power=(android.os.PowerManager)getSystemService(POWER_SERVICE);view=new WebView(this);host=new android.widget.FrameLayout(this);host.addView(view);android.widget.LinearLayout root=new android.widget.LinearLayout(this);root.setOrientation(1);android.widget.Spinner menu=new android.widget.Spinner(this);String[] labels={"Wave Lab","Production Studio","Animation Studio","Physics / Geometry","Offline Graph","Native 3D"};String[] pages={"index.html","production.html","animation.html","lab.html","graph.html"};android.widget.ArrayAdapter<String> adapter=new android.widget.ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels);menu.setAdapter(adapter);menu.setContentDescription("Select studio");menu.setMinimumHeight((int)(48*getResources().getDisplayMetrics().density));root.addView(menu,new android.widget.LinearLayout.LayoutParams(-1,-2));menu.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> parent){}public void onItemSelected(android.widget.AdapterView<?> parent,android.view.View item,int position,long id){if(position==5){if(!nativeMode)switchMode();return;}if(nativeMode)switchMode();view.loadUrl("https://appassets.androidplatform.net/assets/"+pages[position]);}});view.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView w,ValueCallback<android.net.Uri[]> callback,FileChooserParams params){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;try{android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(android.content.Intent.CATEGORY_OPENABLE);intent.setType("*/*");intent.putExtra(android.content.Intent.EXTRA_MIME_TYPES,new String[]{"image/png","image/jpeg","image/webp","audio/*"});startActivityForResult(intent,71);return true;}catch(Exception e){fileCallback=null;callback.onReceiveValue(null);return true;}}});root.addView(host,new android.widget.LinearLayout.LayoutParams(-1,0,1));setContentView(root);WebSettings s=view.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();view.setWebViewClient(new WebViewClient(){public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return loader.shouldInterceptRequest(r.getUrl());}public void onPageFinished(WebView v,String url){thermal.onThermalStatusChanged(power.getCurrentThermalStatus());}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}});view.loadUrl("https://appassets.androidplatform.net/assets/index.html");}private void switchMode(){if(nativeMode){nativeScene.onPause();host.removeView(nativeScene);nativeScene=null;view.setVisibility(android.view.View.VISIBLE);view.resumeTimers();view.onResume();nativeMode=false;return;}android.app.ActivityManager am=(android.app.ActivityManager)getSystemService(ACTIVITY_SERVICE);if(am.getDeviceConfigurationInfo().reqGlEsVersion<0x30000){android.widget.Toast.makeText(this,"OpenGL ES 3 unavailable",0).show();return;}nativeScene=new NativeScene(this);nativeScene.thermal(power.getCurrentThermalStatus());view.onPause();view.pauseTimers();view.setVisibility(android.view.View.GONE);host.addView(nativeScene);nativeMode=true;}protected void onPause(){power.removeThermalStatusListener(thermal);if(nativeScene!=null)nativeScene.onPause();view.onPause();view.pauseTimers();super.onPause();}protected void onResume(){super.onResume();power.addThermalStatusListener(getMainExecutor(),thermal);if(nativeScene!=null)nativeScene.thermal(power.getCurrentThermalStatus());if(nativeScene!=null)nativeScene.onResume();else{view.resumeTimers();view.onResume();thermal.onThermalStatusChanged(power.getCurrentThermalStatus());}}protected void onDestroy(){if(fileCallback!=null){fileCallback.onReceiveValue(null);fileCallback=null;}host.removeAllViews();view.destroy();super.onDestroy();}}
